     8→object ProductMergeStrategy : MergeStrategy<ChangedProductDocument> {
     9→    private val logger by logger()
    10→
    11→    override fun merge(documents: List<ChangedData<ChangedProductDocument>>): List<ChangedData<ChangedProductDocument>> =
    12→        documents
    13→            .groupBy { it.id } // 같은 문서로 그룹핑
    14→            .map { (_, group) ->
    15→                if (group.size == 1) {
    16→                    group.first()
    17→                } else {
    18→                    var isChangedCategory = false
    19→                    var isChangedBrand = false
    20→                    var isChangedManufacturer = false
    21→
    22→                    group
    23→                        .sortedBy { it.offset } // offset 기준으로 정렬
    24→                        .fold(null as ChangedData<ChangedProductDocument>?) { acc, current ->
    25→                            when (current.op) {
    26→                                Operation.CREATE -> {
    27→                                    isChangedCategory = true
    28→                                    // Note. product의 brand, manufacturer 연동은 아직 되고 있지 않지만 미리 작업해둠
    29→                                    isChangedBrand = true
    30→                                    isChangedManufacturer = true
    31→                                }
    32→
    33→                                Operation.UPDATE -> {
    34→                                    // Note. update 메시지의 before가 null인 경우 존재
    35→                                    if (current.beforeData != null && current.afterData != null) {
    36→                                        if (current.beforeData.categoryId != current.afterData.categoryId) isChangedCategory = true
    37→                                        if (current.beforeData.brandId != current.afterData.brandId) isChangedBrand = true
    38→                                        if (current.beforeData.manufacturerId !=
    39→                                            current.afterData.manufacturerId
    40→                                        ) {
    41→                                            isChangedManufacturer = true
    42→                                        }
    43→                                    }
    44→                                }
    45→
    46→                                Operation.DELETE -> {
    47→                                    isChangedCategory = false
    48→                                    isChangedBrand = false
    49→                         ㅈ           isChangedManufacturer = false
    50→                                }
    51→                            }
    52→
    53→                            merge(acc, current)
    54→                                .also {
    55→                                    ㅈ
    56→                                    if (it == null) {
    57→                                        // Note. merge result가 null인 경우, acc는 not null이 보장됨
    58→                                        logger.warn { "[ProductMergeStrategy] Unexpected operation. " + diffLog(acc!!, current) }
    59→                                    }
    60→                                }
    61→                        }.apply {
    62→                            this?.shouldFetchCategory = isChangedCategory
    63→                            this?.shouldFetchBrand = isChangedBrand
    64→                            this?.shouldFetchManufacturer = isChangedManufacturer
    65→                        }
    66→                }
    67→            }.filterNotNull()
