```

### 2.2 GraphQL Query Examples

**CategoryRepositoryImpl** (lines 13-34):
```kotlin
override fun findAllByIds(categoryIds: List<Int>): List<Category> {
    val query = """
        query GetCategories(${'$'}ids: [Int!]!) {
            categories(input: { ids: ${'$'}ids }) {
                items {
                    id
                    name
                    depth
                    idPath
                    namePath
                    status
                }
            }
        }
    """.trimIndent()

    return client.query(
        query = query,
        variables = mapOf("ids" to categoryIds),
        retrievePath = "categories.items",
        Category::class.java,
    )
}
```

**BrandRepositoryImpl** (lines 12-31):
```kotlin
override fun findAllByIds(brandIds: List<Long>): List<Brand> {
    val query = """
        query GetBrands(${'$'}ids: [Long!]!) {
            brands(input: { ids: ${'$'}ids }) {
                items {
                    id
                    name
                }
            }
