### 3.2 Trigger Points in Code

**Entry Point: Kafka Listeners**

**ProductDynamicIndexListener** (lines 22-43):
```kotlin
override fun onMessage(
    data: List<ConsumerRecord<SpecificRecord, SpecificRecord>>,
    acknowledgment: Acknowledgment?,
    consumer: Consumer<*, *>,
) {
    runCatching {
        val changedDocuments = data
            .filter { record ->
                val envelope = record.value() as ProductCdcEnvelope
                val product = envelope.after ?: envelope.before
                product != null && product.categoryId > 0
            }.map { it.toChangedProductData() }

        productIndexApplicationService.indexProducts(changedDocuments)
    }.onSuccess {
        acknowledgment?.acknowledge()
        rewindIfNeeded()
    }.onFailure { ex ->
        logger.error(ex) { "Failed to index products" }
    }.getOrThrow()
}
```

**Application Service Orchestration**

**ProductIndexApplicationService** (lines 21-31):
```kotlin
fun indexProducts(changedData: List<ChangedData<ChangedProductDocument>>): IndexResult {
    val indexDocuments =
        changedData
            .let(ProductMergeStrategy::merge)           // Step 1: Merge & set flags
            .let { productAssembleService.assemble(it) } // Step 2: Fetch & enrich
            .filter(ProductEvaluator::evaluate)         // Step 3: Filter

    legacySyncRepository?.syncProducts(changedData)

    return productIndexRepository.bulk(indexDocuments)
}
```

**Merge Strategy - Determines What to Fetch**

**ProductMergeStrategy** (lines 11-68):
```kotlin
override fun merge(documents: List<ChangedData<ChangedProductDocument>>): List<ChangedData<ChangedProductDocument>> =
    documents
        .groupBy { it.id }
        .map { (_, group) ->
            if (group.size == 1) {
                group.first()
            } else {
                var isChangedCategory = false
                var isChangedBrand = false
                var isChangedManufacturer = false

                group.sortedBy { it.offset }
                    .fold(null as ChangedData<ChangedProductDocument>?) { acc, current ->
                        when (current.op) {
                            Operation.CREATE -> {
                                isChangedCategory = true
                                isChangedBrand = true
                                isChangedManufacturer = true
                            }
                            Operation.UPDATE -> {
                                if (current.beforeData != null && current.afterData != null) {
                                    if (current.beforeData.categoryId != current.afterData.categoryId) 
                                        isChangedCategory = true
                                    if (current.beforeData.brandId != current.afterData.brandId) 
                                        isChangedBrand = true
                                    if (current.beforeData.manufacturerId != current.afterData.manufacturerId) 
                                        isChangedManufacturer = true
                                }
                            }
                            Operation.DELETE -> {
                                isChangedCategory = false
                                isChangedBrand = false
                                isChangedManufacturer = false
                            }
                        }
                        merge(acc, current)
                    }.apply {
                        this?.shouldFetchCategory = isChangedCategory
                        this?.shouldFetchBrand = isChangedBrand
                        this?.shouldFetchManufacturer = isChangedManufacturer
                    }
            }
        }.filterNotNull()
```

**Assemble Service - Extracts IDs to Fetch**

**ProductAssembleService** (lines 19-61):
```kotlin
fun assemble(documents: List<ChangedData<ChangedProductDocument>>): List<IndexDocument<ProductDocument>> {
    val dependencyId = getDependencyId(documents)  // Collect IDs
    val dependency = proxyApplicationService.fetchDependencies(dependencyId)  // FETCH HERE

    return documents.map {
        it.toIndexDocument(
            category = dependency.categories[it.afterData?.categoryId],
            brand = dependency.brands[it.afterData?.brandId],
            manufacturer = dependency.manufacturers[it.afterData?.manufacturerId],
        )
    }
}

fun getDependencyId(documents: List<ChangedData<ChangedProductDocument>>): DependencyId {
    val categoryIds: MutableList<Int> = mutableListOf()
    val brandIds: MutableList<Long> = mutableListOf()
    val manufacturerIds: MutableList<Long> = mutableListOf()
    val mallIds: MutableList<Int> = mutableListOf()

    documents.forEach {
        if (it.shouldFetchCategory) categoryIds.add(it.afterData!!.categoryId)
        if (it.shouldFetchBrand) it.afterData?.brandId?.run { brandIds.add(this) }
        if (it.shouldFetchManufacturer) it.afterData?.manufacturerId?.run { manufacturerIds.add(this) }
        if (it.shouldFetchMall) it.afterData?.mallId?.run { mallIds.add(this) }
    }

    return DependencyId(
        categoryIds = categoryIds.distinct(),
        brandIds = brandIds.distinct(),
        manufacturerIds = manufacturerIds.distinct(),
    )
}
```

**Parallel Proxy Fetching - ACTUAL PROXY API CALLS**

**ProxyApplicationService** (lines 25-67):
```kotlin
fun fetchDependencies(dependencyId: DependencyId): Dependency =
    runBlocking(Dispatchers.IO) {
        // All 4 calls execute IN PARALLEL using async
        val categoriesDeferred = async {
            if (dependencyId.categoryIds.isEmpty()) {
                emptyMap()
            } else {
                categoryService.getCategories(dependencyId.categoryIds)
                    .associateBy { it.id }
            }
        }
        val brandsDeferred = async {
            if (dependencyId.brandIds.isEmpty()) {
                emptyMap()
            } else {
                brandService.getBrands(dependencyId.brandIds)
                    .associateBy { it.id }
            }
        }
        val manufacturersDeferred = async {
            if (dependencyId.manufacturerIds.isEmpty()) {
                emptyMap()
            } else {
                manufacturerService.getManufacturers(dependencyId.manufacturerIds)
                    .associateBy { it.id }
            }
        }
        val mallsDeferred = async {
            if (dependencyId.mallIds.isEmpty()) {
                emptyMap()
            } else {
                mallService.getMalls(dependencyId.mallIds)
                    .associateBy { it.mallId }
            }
        }

        Dependency(
            categories = categoriesDeferred.await(),
            brands = brandsDeferred.await(),
            manufacturers = manufacturersDeferred.await(),
            malls = mallsDeferred.await(),
        )
    }
```

